import type { CommentChange } from "./diff";

const BREAKPOINT = "\n--> statement-breakpoint\n";

const identifier = (name: string) => `"${name.replace(/"/g, '""')}"`;

const literal = (value: string | null) => (value === null ? "NULL" : `'${value.replace(/'/g, "''")}'`);

// Objects without a schema are left unqualified, the same as the DDL generated by drizzle-kit
const qualifiedName = (schema: string | undefined, name: string) =>
  schema ? `${identifier(schema)}.${identifier(name)}` : identifier(name);

/** The name of the table or the enum the change belongs to. */
const objectName = (change: CommentChange) =>
  qualifiedName(change.schema, change.target === "enum" ? change.name : change.table);

const statement = (change: CommentChange) => {
  switch (change.target) {
    case "enum":
      return `COMMENT ON TYPE ${objectName(change)} IS ${literal(change.comment)};`;
    case "table":
      return `COMMENT ON TABLE ${objectName(change)} IS ${literal(change.comment)};`;
    case "column":
      return `COMMENT ON COLUMN ${objectName(change)}.${identifier(change.column)} IS ${literal(change.comment)};`;
  }
};

/** Builds the content of the migration file, with a block of statements per table or enum. */
export function toPostgresSql(changes: CommentChange[]): string {
  const blocks = new Map<string, { name: string; statements: string[] }>();
  for (const change of changes) {
    const name = objectName(change);
    // Keyed by the kind as well, so that a table and an enum are not mixed up
    const key = `${change.target === "enum" ? "enum" : "table"}:${name}`;
    const block = blocks.get(key) ?? { name, statements: [] };
    block.statements.push(statement(change));
    blocks.set(key, block);
  }
  const body = [...blocks.values()].map(({ name, statements }) => `-- ${name}\n${statements.join(BREAKPOINT)}`);
  return `-- Generated by drizzle-db-comments-generator\n\n${body.join(`${BREAKPOINT}\n`)}\n`;
}
